  const format = bestAcceptedFormat(request.headers["accept"]);
  logger.info({
    message: `accepted format: ${format}`
  });
  const result = getFromExternal2 ? await getOptimisedImageFromExternal(imagePath, width, Math.min(quality, 75), format) : await getOptimisedImageFromS3(imagePath, width, Math.min(quality, 75), format);
  if (result === undefined) {
    return {
      statusCode: "404",
      body: "Not Found",
      headers: {
        "Content-Type": "text/plain"
      }
    };
  }
